public long connectRopes(int[] ropes) {
    List<Long> pool = new ArrayList<>();
    for (int r : ropes) {
        pool.add((long) r);
    }
    long total = 0;
    while (pool.size() > 1) {
        int i1 = smallestIndex(pool, -1);
        int i2 = smallestIndex(pool, i1);
        long sum = pool.get(i1) + pool.get(i2);
        total += sum;
        // Remove the larger index first so the other index stays valid.
        pool.remove(Math.max(i1, i2));
        pool.remove(Math.min(i1, i2));
        pool.add(sum);
    }
    return total;
}

private int smallestIndex(List<Long> pool, int skip) {
    int best = -1;
    for (int i = 0; i < pool.size(); i++) {
        if (i == skip) {
            continue;
        }
        if (best == -1 || pool.get(i) < pool.get(best)) {
            best = i;
        }
    }
    return best;
}

public long connectRopes(int[] ropes) {
    PriorityQueue<Long> heap = new PriorityQueue<>();
    for (int r : ropes) {
        heap.offer((long) r);
    }
    long total = 0;
    while (heap.size() > 1) {
        long a = heap.poll();
        long b = heap.poll();
        long sum = a + b;
        total += sum;
        heap.offer(sum);
    }
    return total;
}

